	token := registerAndSignIn(t, srv)

	png := media.FixtureHeroMountain
	digest := hexSHA256(png)
	postJSON(t, srv, token, "/v1/media", beginBody(digest, len(png), "image/png"))
	bucket.Put(t, digest, png)
	postJSON(t, srv, token, "/v1/media/"+digest+"/commit", nil)

